# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">VEDA HUTBESİ VE İKİ EMANET (SEKALEYN) HADİSİ</text>\n  <!-- Ust Hadis Kutusu -->\n  <rect x="35" y="42" width="630" height="58" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="350" y="65" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">"Size iki emanet bırakıyorum; onlara sımsıkı sarıldığınız sürece</text>\n  <text x="350" y="85" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">yolunuzu şaşırmazsınız: Allah\'ın vahyi Kur\'an ve Peygamberinin sünneti."</text>\n  <!-- Sol: 1. Emanet -->\n  <rect x="35" y="114" width="300" height="130" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="185" y="138" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">1. EMANET: KUR\'AN-I KERİM</text>\n  <text x="52" y="162" font-size="11.5" fill="#14532d">• Yüce Allah\'ın son ilahi vahyidir.</text>\n  <text x="52" y="184" font-size="11.5" fill="#14532d">• İnanç, ibadet ve ahlakın ana kaynağıdır.</text>\n  <text x="52" y="206" font-size="11.5" fill="#14532d">• Zümer, 9: İlim ve hikmet rehberidir.</text>\n  <text x="52" y="228" font-size="11.5" font-weight="bold" fill="#15803d">• Sözlerin en doğrusu Allah\'ın kelamıdır.</text>\n  <!-- Sag: 2. Emanet -->\n  <rect x="365" y="114" width="300" height="130" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="515" y="138" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">2. EMANET: SÜNNET-İ SENİYYE</text>\n  <text x="382" y="162" font-size="11.5" fill="#78350f">• Kur\'an\'ın yaşayan açıklaması ve uygulamasıdır.</text>\n  <text x="382" y="184" font-size="11.5" fill="#78350f">• Müminler için en güzel örnektir (üsve-i hasene).</text>\n  <text x="382" y="206" font-size="11.5" fill="#78350f">• İbadetlerin yapılış şeklini öğretir (tebyin).</text>\n  <text x="382" y="228" font-size="11.5" font-weight="bold" fill="#b45309">• Rehberliğin en güzeli Muhammed\'in yoludur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İTİSAM HADİSİ VE DİNİN SAFLIĞINI KORUMA</text>\n  <!-- Kutu 1: Sahih Yol -->\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">İTİSAM (SAHİH YOL)</text>\n  <rect x="34" y="82" width="182" height="44" rx="6" fill="#dcfce7"/>\n  <text x="125" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">Buhârî, İ\'tisâm, 2</text>\n  <text x="125" y="117" text-anchor="middle" font-size="10.5" fill="#166534">Kur\'an ve Sünnete Tutunma</text>\n  <text x="34" y="148" font-size="11" fill="#14532d">• Sözün en doğrusu: Kur\'an.</text>\n  <text x="34" y="170" font-size="11" fill="#14532d">• Yolun en güzeli: Sünnet.</text>\n  <text x="34" y="192" font-size="11" fill="#14532d">• Dinin aslını bozulmadan</text>\n  <text x="42" y="208" font-size="11" fill="#14532d">koruma ve yaşama bilinci.</text>\n  <!-- Kutu 2: Bidat -->\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">BİDAT (MUHDESÂT)</text>\n  <rect x="259" y="82" width="182" height="44" rx="6" fill="#ffedd5"/>\n  <text x="350" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#7c2d12">Dinde Sonradan Uydurulanlar</text>\n  <text x="350" y="117" text-anchor="middle" font-size="10.5" fill="#9a3412">İnanç ve İbadete Ekleme/Çıkarma</text>\n  <text x="259" y="148" font-size="11" fill="#7c2d12">• Asr-ı saadette olmayıp dine</text>\n  <text x="267" y="164" font-size="11" fill="#7c2d12">ibadet diye eklenen şeylerdir.</text>\n  <text x="259" y="186" font-size="11" fill="#7c2d12">• Bilimsel ve teknolojik gelişmeler</text>\n  <text x="267" y="202" font-size="11" font-weight="bold" fill="#c2410c">bidat değildir.</text>\n  <!-- Kutu 3: Hurafe ve Heva -->\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">HURAFE VE HEVA</text>\n  <rect x="484" y="82" width="182" height="44" rx="6" fill="#fee2e2"/>\n  <text x="575" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#7f1d1d">Batıl İnanç ve Keyfî Arzu</text>\n  <text x="575" y="117" text-anchor="middle" font-size="10.5" fill="#991b1b">Tevhid ve Sünnetten Sapma</text>\n  <text x="484" y="148" font-size="11" fill="#7f1d1d">• Hurafe: Akla ve dine aykırı</text>\n  <text x="492" y="164" font-size="11" fill="#7f1d1d">batıl inançlar (fal, çaput vb.).</text>\n  <text x="484" y="186" font-size="11" fill="#7f1d1d">• Heva: Vahyi bırakıp nefsin</text>\n  <text x="492" y="202" font-size="11" fill="#7f1d1d">arzularını ölçü edinmektir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ZEYD BİN HÂRİSE ÖRNEĞİ VE PEYGAMBERİMİZE İTAAT KAVRAMLARI</text>\n  <!-- Sol: Zeyd bin Harise -->\n  <rect x="25" y="42" width="315" height="202" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">ZEYD BİN HÂRİSE VE MUHABBET</text>\n  <rect x="42" y="78" width="280" height="52" rx="6" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="182" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">"Ben sende öyle bir şefkat ve ahlak gördüm ki,</text>\n  <text x="182" y="114" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">senin yerine hiç kimseyi tercih etmem!"</text>\n  <text x="42" y="152" font-size="11.5" fill="#581c87">• Babası Hârise ve amcası Kâb onu götürmeye geldi.</text>\n  <text x="42" y="174" font-size="11.5" fill="#581c87">• Hz. Peygamber fidyesiz olarak seçimi Zeyd\'e bıraktı.</text>\n  <text x="42" y="196" font-size="11.5" fill="#581c87">• Zeyd, Hz. Peygamber\'in yanında kalmayı seçti.</text>\n  <text x="42" y="218" font-size="11.5" font-weight="bold" fill="#7e22ce">• Kur\'an\'da adı açıkça geçen tek sahabidir (Ahzâb, 37).</text>\n  <!-- Sag: Temel Kavramlar -->\n  <rect x="360" y="42" width="315" height="202" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">TEMEL KAVRAMLAR ÖZETİ</text>\n  <text x="378" y="92" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Habîbullah:</tspan> Allah\'ın sevgili kulu ve elçisi.</text>\n  <text x="378" y="114" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Üsve-i Hasene:</tspan> En güzel ahlaki örnek (Ahzâb, 21).</text>\n  <text x="378" y="136" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">İtaat:</tspan> Peygamber\'e uymak Allah\'a uymaktır (Nisâ, 80).</text>\n  <text x="378" y="158" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">İtisam:</tspan> Kur\'an ve sünnete sımsıkı sarılmak.</text>\n  <text x="378" y="180" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Muâhât:</tspan> Ensar ile Muhacir kardeşliği.</text>\n  <text x="378" y="202" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Salatüselam:</tspan> Peygamberimize dua ve selam (Ahzâb, 56).</text>\n  <text x="378" y="224" font-size="11.5" font-weight="bold" fill="#1d4ed8">• <tspan font-weight="bold">Sünnet / Hadis:</tspan> Söz, fiil ve takrirlerinin bütünü.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
